import{_ as t}from"./chunks/2022-05-25-10-21-15.upAdkre_.js";import{_ as r,o as a,c as o,a2 as i}from"./chunks/framework.CdjpmwdR.js";const y=JSON.parse('{"title":"Router, Proxy, Gateway: Boundaries and Relationships","description":"A boundary‑first distinction between routers, proxies, and gateways by network layer and responsibility, preventing terminology mixing in architecture discussions.","frontmatter":{"category":"node","date":"2022-05-01","title":"Router, Proxy, Gateway: Boundaries and Relationships","description":"A boundary‑first distinction between routers, proxies, and gateways by network layer and responsibility, preventing terminology mixing in architecture discussions.","tags":["node","api-design"],"image":"/blogs/assets/202205-router-proxy-gtw/2022-05-25-10-21-15.png"},"headers":[],"relativePath":"en/blogs/2022/202205-router-proxy-gtw.md","filePath":"en/blogs/2022/202205-router-proxy-gtw.md"}'),n={name:"en/blogs/2022/202205-router-proxy-gtw.md"};function s(l,e,d,c,u,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<p>While reading <a href="https://mp.weixin.qq.com/s/B0LVmFvI7kFtjFEM0FG_zw" target="_blank" rel="noreferrer">《为什么需要可编程代理》</a>, I noticed that &quot;router&quot;, &quot;proxy&quot;, and &quot;gateway&quot; are often discussed together, but many teams use these words with different meanings.</p><p>This note uses <strong>working layer + primary responsibility</strong> to align terminology so that network, platform, and API design discussions can converge quickly.</p><h2 id="router-forwarding-packets-between-networks" tabindex="-1">Router: forwarding packets between networks <a class="header-anchor" href="#router-forwarding-packets-between-networks" aria-label="Permalink to &quot;Router: forwarding packets between networks&quot;">​</a></h2><ul><li><strong>Router</strong><ul><li>Hardware router <ul><li>Works at Layer 3 of the network stack.</li><li>Transparent to endpoints on both sides; hosts on internal and external networks do not know a router is involved.</li><li>Can work at a low level by rewriting network addresses and forwarding packets directly, usually faster than an app lication‑level proxy.</li></ul></li><li>Software router <ul><li>Combines software logic to intercept, modify, and forward packets.</li><li>In practice often behaves similarly to a proxy server.</li></ul></li></ul></li></ul><h2 id="proxy-acting-on-behalf-of-clients-or-servers" tabindex="-1">Proxy: acting on behalf of clients or servers <a class="header-anchor" href="#proxy-acting-on-behalf-of-clients-or-servers" aria-label="Permalink to &quot;Proxy: acting on behalf of clients or servers&quot;">​</a></h2><ul><li><p><strong>Proxy server</strong></p><ul><li>Operates above Layer 3, usually at Layer 4 or 7.</li><li>Often the only machine in a LAN that can access the internet. Clients must send requests to the proxy, which then forwards and returns responses. <ul><li>Can cache HTTP content, apply application‑level filtering and authorization, etc.</li></ul></li><li>Different proxy products expose different capabilities (WWW, FTP, …).</li><li>Typically connects endpoints that speak the <strong>same protocol stack</strong> — its main job is forwarding.</li></ul></li><li><p><strong>Proxy modes</strong></p><ul><li><strong>Forward proxy</strong> — proxying external addresses (typical &quot;climb the wall&quot; setup). <ul><li>NAT rewrites destination address/port after unpacking packets.</li></ul></li><li><strong>Reverse proxy</strong> — exposing a single public address for multiple backend servers. <ul><li>Load balancers are a specialized form of reverse proxy. <ul><li>Load balancing is the <em>goal</em>; reverse proxy is the <em>mechanism</em>.</li></ul></li></ul></li></ul></li></ul><h2 id="gateway-boundary-between-heterogeneous-networks-or-systems" tabindex="-1">Gateway: boundary between heterogeneous networks or systems <a class="header-anchor" href="#gateway-boundary-between-heterogeneous-networks-or-systems" aria-label="Permalink to &quot;Gateway: boundary between heterogeneous networks or systems&quot;">​</a></h2><ul><li><strong>Gateway</strong><ul><li>A conceptual term: any device that connects two different networks can be called a gateway.</li><li>Typically connects endpoints that use <strong>different protocols</strong> — protocol translation is the key.</li><li><strong>Broad sense</strong>: anything with traffic coming in and out can be called a gateway.</li><li><strong>Narrow sense</strong>: <ul><li>In IP routing: the boundary of a subnet. All traffic entering or leaving the subnet must first reach the (default) gateway.<br> See: <a href="https://www.zhihu.com/question/21787311" target="_blank" rel="noreferrer">网关和路由器的区别是什么？</a></li><li>API gateway: intercepts, monitors, transforms, and forwards HTTP APIs.</li></ul></li></ul></li></ul><h2 id="summary-start-from-boundaries-then-capabilities" tabindex="-1">Summary: start from boundaries, then capabilities <a class="header-anchor" href="#summary-start-from-boundaries-then-capabilities" aria-label="Permalink to &quot;Summary: start from boundaries, then capabilities&quot;">​</a></h2><p><img src="'+t+'" alt="Route vs Proxy vs Gateway"></p><blockquote><p>PS: I also looked into adding Chinese fonts to Excalidraw:</p><ul><li>Issue: <a href="https://github.com/excalidraw/excalidraw/issues/5245" target="_blank" rel="noreferrer">https://github.com/excalidraw/excalidraw/issues/5245</a></li><li>Spike: <a href="https://github.com/Anddd7/excalidraw/commit/97eca3fd347c9d3f3875996e7c49585307264e4e" target="_blank" rel="noreferrer">https://github.com/Anddd7/excalidraw/commit/97eca3fd347c9d3f3875996e7c49585307264e4e</a></li><li>Demo: <a href="https://excalidraw-anddd7.vercel.app/" target="_blank" rel="noreferrer">https://excalidraw-anddd7.vercel.app/</a></li></ul></blockquote>',11)])])}const w=r(n,[["render",s]]);export{y as __pageData,w as default};
